import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { isProxyStorageKey } from "./saveKeys.js";

// The per-game cloud save registry: every game that can have a cloud save,
// keyed by its stable id. Generated by scripts/build-save-registry.js; the
// browser reads the same file. See docs/cloud-saves.md.
const REGISTRY_PATH = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../static/assets/json/saves.json",
);

export const GAME_ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,95}$/;
export const SLOT_PATTERN = /^[a-z0-9][a-z0-9-]{0,31}$/;
export const DEFAULT_SLOT = "default";

// Query parameters that pick the game inside a shared player page, such as
// the Flash player at /misc/flash/index.html?swf=<file>.
const GAME_QUERY_PARAMS = ["swf", "game", "rom"];

// A game's id from the address of its document. static/assets/js/save-agent.js
// and cloud-saves.js carry the same function and the three must match: the id
// is what every save is stored under.
export function gameIdFromLocation(pathname, search = "") {
  let decoded = String(pathname || "");
  try {
    decoded = decodeURIComponent(decoded);
  } catch {}
  const match = /^\/misc\/(.+)$/.exec(decoded);
  if (!match) return null;
  const rest = match[1]
    .replace(/\/index\.html?$/i, "")
    .replace(/\.html?$/i, "")
    .replace(/\/+$/, "");
  if (!rest || /^(play|media)(\/|$)/i.test(rest)) return null;

  let id = rest;
  const params = new URLSearchParams(search || "");
  for (const name of GAME_QUERY_PARAMS) {
    const value = params.get(name);
    if (value) {
      id += "-" + value.replace(/\.[a-z0-9]+$/i, "");
      break;
    }
  }
  id = id
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 96)
    .replace(/-+$/, "");
  return GAME_ID_PATTERN.test(id) ? id : null;
}

// localStorage keys that belong to the site, never to a game: the signed-in
// account, settings, and the proxy's copies of other sites' storage. A game
// save holding one is refused. save-agent.js carries the same list.
const SITE_KEYS = new Set([
  "uuid",
  "username",
  "premium",
  "siteTheme",
  "tab",
  "aboutBlank",
  "adPrefs",
  "panicKey",
  "PanicLink",
  "pokiMigrated",
]);
const SITE_KEY_PATTERNS = [
  /^55gms/i,
  /^gms[-:._]/i,
  /^__gms/i,
  /^[a-z]+-(last-body|viewed)$/,
];

export function isSiteStorageKey(key) {
  const text = String(key);
  if (SITE_KEYS.has(text)) return true;
  if (SITE_KEY_PATTERNS.some((pattern) => pattern.test(text))) return true;
  return isProxyStorageKey(text);
}

let registry = null;

function loadRegistry() {
  if (registry) return registry;
  try {
    const parsed = JSON.parse(readFileSync(REGISTRY_PATH, "utf8"));
    registry = parsed && typeof parsed.games === "object" ? parsed : null;
  } catch (error) {
    console.warn(`[saves] cannot read ${REGISTRY_PATH}: ${error.message}`);
  }
  registry ||= { version: 0, games: {} };
  return registry;
}

// The registry entry for a game id, or null when it has none.
export function getGame(gameId) {
  if (typeof gameId !== "string" || !GAME_ID_PATTERN.test(gameId)) return null;
  const games = loadRegistry().games;
  return Object.hasOwn(games, gameId) ? games[gameId] : null;
}

// Whether a game's saves can go to the cloud at all.
export function isSyncable(game) {
  return Boolean(game) && game.status !== "local-only";
}
